    name: { de: "Kernkraftwerk Tihange", hu: "Tihange-i atomerőmű", ro: "Centrala Nucleară de la Tihange", en: "Tihange Nuclear Power Plant"},
    image: "/poi-images/belgium-tihange-nuclear-plant-economic-v2.webp",
