    type: "factory",
    name: { de: "Biotech-Zentrum Wavre", hu: "Wavre-i biotechnológiai központ", ro: "Centrul de biotehnologie din Wavre", en: "Wavre Biotech Hub"},
    image: "/poi-images/belgium-wavre-biotech-hub-economic-v2.webp",
    coords: [4.588, 50.728],
